import XCTest
@testable import MakeReady

final class InvitationModelsTests: XCTestCase {
    func testFeedDoesNotAdmitDetailOnlyWithdrawnStatus() {
        let json = #"{"id":"i1","kind":"invite","status":"withdrawn","recipientPhone":null,"recipientName":null,"memberId":null,"groupId":null,"groupName":null,"organizationId":"org1","inviterId":null,"inviterName":null,"date":"2026-11-02T12:00:00Z","createdAt":"2026-11-02T12:00:00Z"}"#
        XCTAssertThrowsError(try JSONDecoder.apiDecoder.decode(InvitationFeedItem.self, from: Data(json.utf8)))
    }
    // Producer freeze 46d0b8c6: actual handoff examples, embedded so XCTest needs no repo files.
    func testFrozenProducerExamplesDecodeWithoutLegacyEnvelope() throws {
        let c1 = try JSONDecoder.apiDecoder.decode(InvitationFeedResponse.self, from: Data(#"{"items":[{"id":"a1100000-0000-4000-8000-000000000052","kind":"request","status":"rejected","recipientPhone":"+12025550102","recipientName":null,"memberId":"a1100000-0000-4000-8000-000000000012","groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","organizationId":"a1100000-0000-4000-8000-000000000003","inviterId":null,"inviterName":null,"date":"2025-02-02T00:00:00.000Z","createdAt":"2025-01-02T03:04:07.000Z"},{"id":"a1100000-0000-4000-8000-000000000051","kind":"request","status":"accepted","recipientPhone":"+12025550101","recipientName":null,"memberId":"a1100000-0000-4000-8000-000000000011","groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","organizationId":"a1100000-0000-4000-8000-000000000003","inviterId":null,"inviterName":null,"date":"2025-02-02T00:00:00.000Z","createdAt":"2025-01-02T03:04:06.000Z"},{"id":"a1100000-0000-4000-8000-000000000031","kind":"invite","status":"accepted","recipientPhone":"+12025550201","recipientName":null,"memberId":null,"groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","organizationId":"a1100000-0000-4000-8000-000000000003","inviterId":"a1100000-0000-4000-8000-000000000001","inviterName":"Legacy Leader","date":"2025-02-01T00:00:00.000Z","createdAt":"2025-01-02T03:04:06.000Z"},{"id":"a1100000-0000-4000-8000-000000000037","kind":"invite","status":"sent","recipientPhone":"+12025550106","recipientName":null,"memberId":null,"groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","organizationId":"a1100000-0000-4000-8000-000000000003","inviterId":"a1100000-0000-4000-8000-000000000001","inviterName":"Legacy Leader","date":"2025-01-02T03:04:12.000Z","createdAt":"2025-01-02T03:04:12.000Z"},{"id":"a1100000-0000-4000-8000-000000000035","kind":"invite","status":"sent","recipientPhone":null,"recipientName":null,"memberId":null,"groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","organizationId":"a1100000-0000-4000-8000-000000000003","inviterId":"a1100000-0000-4000-8000-000000000001","inviterName":"Legacy Leader","date":"2025-01-02T03:04:10.000Z","createdAt":"2025-01-02T03:04:10.000Z"},{"id":"a1100000-0000-4000-8000-000000000034","kind":"invite","status":"sent","recipientPhone":"+12025550204","recipientName":"Recipient 4","memberId":null,"groupId":null,"groupName":null,"organizationId":"a1100000-0000-4000-8000-000000000003","inviterId":"a1100000-0000-4000-8000-000000000001","inviterName":"Legacy Leader","date":"2025-01-02T03:04:09.000Z","createdAt":"2025-01-02T03:04:09.000Z"},{"id":"a1100000-0000-4000-8000-000000000032","kind":"invite","status":"expired","recipientPhone":"+12025550202","recipientName":"Recipient 2","memberId":null,"groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","organizationId":"a1100000-0000-4000-8000-000000000003","inviterId":"a1100000-0000-4000-8000-000000000001","inviterName":"Legacy Leader","date":"2025-01-02T03:04:07.000Z","createdAt":"2025-01-02T03:04:07.000Z"},{"id":"a1100000-0000-4000-8000-000000000050","kind":"request","status":"requested","recipientPhone":"+12025550100","recipientName":null,"memberId":"a1100000-0000-4000-8000-000000000010","groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","organizationId":"a1100000-0000-4000-8000-000000000003","inviterId":null,"inviterName":null,"date":"2025-01-02T03:04:05.000Z","createdAt":"2025-01-02T03:04:05.000Z"},{"id":"a1100000-0000-4000-8000-000000000030","kind":"invite","status":"sent","recipientPhone":"+12025550200","recipientName":"Recipient 0","memberId":null,"groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","organizationId":"a1100000-0000-4000-8000-000000000003","inviterId":"a1100000-0000-4000-8000-000000000001","inviterName":"Legacy Leader","date":"2025-01-02T03:04:05.000Z","createdAt":"2025-01-02T03:04:05.000Z"},{"id":"a1100000-0000-4000-8000-000000000033","kind":"invite","status":"expired","recipientPhone":"+12025550203","recipientName":null,"memberId":null,"groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","organizationId":"a1100000-0000-4000-8000-000000000003","inviterId":"a1100000-0000-4000-8000-000000000001","inviterName":"Legacy Leader","date":"2020-01-01T00:00:00.000Z","createdAt":"2025-01-02T03:04:08.000Z"}],"total":10,"filters":{"orgs":[{"id":"a1100000-0000-4000-8000-000000000003","name":"Legacy Organization"}],"groups":[{"id":"a1100000-0000-4000-8000-000000000004","name":"Legacy Group","organizationId":"a1100000-0000-4000-8000-000000000003"}],"leaders":[{"id":"a1100000-0000-4000-8000-000000000001","name":"Legacy Leader"}]}}"#.utf8))
        let c2 = try JSONDecoder.apiDecoder.decode(InvitationDetail.self, from: Data(#"{"id":"a1100000-0000-4000-8000-000000000030","kind":"invite","status":"sent","recipientPhone":"+12025550200","recipientName":"Recipient 0","inviterName":"Legacy Leader","message":null,"createdAt":"2025-01-02T03:04:05.000Z","member":null,"invitations":[{"id":"a1100000-0000-4000-8000-000000000030","kind":"invite","groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","groupPicture":null,"status":"sent","date":"2025-01-02T03:04:05.000Z"}],"events":[],"canResend":true,"canWithdraw":true}"#.utf8))
        let c3 = try JSONDecoder.apiDecoder.decode(InvitationDetail.self, from: Data(#"{"id":"a1100000-0000-4000-8000-000000000030","kind":"invite","status":"sent","recipientPhone":"+12025550200","recipientName":"Recipient 0","inviterName":"Legacy Leader","message":null,"createdAt":"2025-01-02T03:04:05.000Z","member":null,"invitations":[{"id":"a1100000-0000-4000-8000-000000000030","kind":"invite","groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","groupPicture":null,"status":"sent","date":"2025-01-02T03:04:05.000Z"}],"events":[{"id":"1473459c-99cf-461e-9b3f-f22861e734ec","type":"resent","at":"2026-11-02T09:02:51.510Z","groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","invitationId":"a1100000-0000-4000-8000-000000000030"}],"canResend":true,"canWithdraw":true}"#.utf8))
        let c4 = try JSONDecoder.apiDecoder.decode(InvitationDetail.self, from: Data(#"{"id":"a1100000-0000-4000-8000-000000000030","kind":"invite","status":"withdrawn","recipientPhone":"+12025550200","recipientName":"Recipient 0","inviterName":"Legacy Leader","message":null,"createdAt":"2025-01-02T03:04:05.000Z","member":null,"invitations":[{"id":"a1100000-0000-4000-8000-000000000030","kind":"invite","groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","groupPicture":null,"status":"withdrawn","date":"2025-01-02T03:04:05.000Z"}],"events":[{"id":"acd92069-3a75-4ba1-9765-7025f808545b","type":"withdrawn","at":"2026-11-02T09:02:51.536Z","groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","invitationId":"a1100000-0000-4000-8000-000000000030"},{"id":"1473459c-99cf-461e-9b3f-f22861e734ec","type":"resent","at":"2026-11-02T09:02:51.510Z","groupId":"a1100000-0000-4000-8000-000000000004","groupName":"Legacy Group","invitationId":"a1100000-0000-4000-8000-000000000030"}],"canResend":false,"canWithdraw":false}"#.utf8))
        XCTAssertEqual(c1.items.count, 10)
        XCTAssertEqual(Set(c1.items.map(\.status.rawValue)), Set(["sent", "requested", "accepted", "rejected", "expired"]))
        XCTAssertTrue(c1.items.contains { $0.recipientPhone == nil })
        XCTAssertTrue(c1.items.contains { $0.groupId == nil })
        XCTAssertEqual(c2.selectedInvitation?.id, c2.id)
        XCTAssertEqual(c3.events.first?.type, .resent)
        XCTAssertEqual(c4.events.first?.type, .withdrawn)
        XCTAssertFalse(c4.canWithdraw)
    }

    func testNullableDetailRetainsAbsentMetadataAndHistoricalStatus() throws {
        let json = #"{"id":"i1","kind":"invite","status":"withdrawn","recipientPhone":null,"recipientName":null,"inviterName":null,"message":null,"createdAt":"2025-01-02T03:04:05.000Z","member":{"id":"m1","name":"Ada","picture":null,"age":null,"role":null,"birthday":null,"joinedAt":null},"invitations":[{"id":"i1","kind":"invite","groupId":null,"groupName":null,"groupPicture":null,"status":"withdrawn","date":"2025-01-02T03:04:05.000Z"}],"events":[],"canResend":false,"canWithdraw":false}"#
        let detail = try JSONDecoder.apiDecoder.decode(InvitationDetail.self, from: Data(json.utf8))
        XCTAssertNil(detail.recipientPhone)
        XCTAssertNil(detail.invitations.first?.groupId)
        XCTAssertNil(detail.member?.age)
        XCTAssertEqual(detail.status, .withdrawn)
        XCTAssertEqual(detail.createdAt, "2025-01-02T03:04:05.000Z")
        XCTAssertFalse(detail.canResend)
    }
}
